import{z as s,x as B,o as t,c as p,q as l,j as n,D as e,d as r,s as A,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"反应离子刻蚀转印","description":"","frontmatter":{"title":"反应离子刻蚀转印","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/rie-pattern-transfer.md","filePath":"litho/rie-pattern-transfer.md","lastUpdated":1791413859000}'),d={name:"litho/rie-pattern-transfer.md"};function D(h,a,m,C,I,f){const i=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="反应离子刻蚀转印" tabindex="-1">反应离子刻蚀转印 <a class="header-anchor" href="#反应离子刻蚀转印" aria-label="Permalink to &quot;反应离子刻蚀转印&quot;">​</a></h1><div class="epigraph"><p>显影只留下一层有机浮雕。器件要的是硬掩模或硅上的永久边；把胶图形变成那条边的，是离子与中性自由基的协同，而不是再一次投影成像。</p><footer>—— 对照 Coburn–Winters 对等离子体表面协同的论述，以及刻蚀教材把 RIE 写成各向异性转印</footer></div><p><a href="/litho/metal-via-co-optimization">上一课</a>把金属与 via 钉进同一张网格，替仿真、模型与验证课程收尾；本课起一门新课——制程、封装与管制。缺口是：<a href="/litho/etch-model-calibration">刻蚀模型校准</a>把刻蚀收成 OPC 里的紧凑偏置之后，这条偏置在腔体里从哪来还没有回答。本课钉反应离子刻蚀（RIE）：胶图形如何转到硬掩模和硅。<a href="/litho/litho-process-flow">光刻流程</a>已经排过「显影之后才转印」；这里不重讲涂胶顺序，只补转移函数的物理。深宽比与负荷如何让速率随开口变，留给<a href="/litho/etch-loading-ar">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>先进节点胶薄，选择比不够直接啃硅或厚介质。产线先把胶转到 SOC / SiARC、氮化物或金属硬掩模，再往下刻。若把显影后 SEM 当成栅极 CD，是把转印偏置算进了镜头。校准课的紧凑核假定存在一个稳定的「胶 → 衬底」映射；映射一漂，全芯片 OPC 跟着漂。</p><p>缺口因此是：各向异性从哪来、选择比怎么买、以及为何离子能量与化学不能只拧一个。纯溅射损伤大、侧壁差；纯化学各向同性，细线立不住。RIE 要的是两者协同。</p><p><span class="marginnote">直觉类比：只点蜡烛（纯化学）烧不动硬漆，只拿锤子（纯离子）砸也慢还伤底材；先用化学把表面「泡软」，再一锤敲掉——这一软一硬的接力就是 Coburn–Winters 协同。</span></p><h3 id="胶不是理想二元掩模" tabindex="-1">胶不是理想二元掩模 <a class="header-anchor" href="#胶不是理想二元掩模" aria-label="Permalink to &quot;胶不是理想二元掩模&quot;">​</a></h3><p>胶边有斜角、LWR 和残胶。等离子体先看到的是这层形貌，不是版图。选择比不够时，胶顶被削，开口变宽，CD 随刻蚀时间走。硬掩模的作用是把「成像预算」和「深度预算」拆开：薄胶只负责定义边，纵向深度交给更耐打的膜。这与 <a href="/litho/ald-ale">ALD/ALE</a> 的循环修整是同一纵向危机的两种回答，本课先停在连续 RIE。</p><p><span class="marginnote">ADI 与 AEI 必须分开报。把刻蚀后 CD 写进扫描仪分辨率规格，是类别错误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>RIE 在低气压等离子体里同时提供：垂直入射的离子，以及能与表面反应的中性自由基。Coburn 与 Winters 的经典图像是协同——离子轰击或电子协助让本不会快速挥发的反应进行；关掉离子，化学速率掉下去；只开离子，物理溅射也慢。各向异性来自离子的方向性，侧壁靠钝化膜挡住横向吃。</p><p>工艺旋钮是源功率、偏置功率、气压、气体比和温度。偏置抬离子能量，剖面变直，损伤与选择比恶化。聚合物气体（如含氟碳）在侧壁沉积，窗口是「够钝化而不封口」。硬掩模打开后，硅或介质用另一套化学，胶可能已经所剩无几。教材把这条链写成：显影浮雕 → 开硬掩模 → 主刻 → 过刻 → 去胶；每段有自己的终点探测。</p>',13)),(t(),n(o,null,{default:e(()=>[A(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E6%98%BE%E5%BD%B1%E8%83%B6%E6%B5%AE%E9%9B%95%22%5D%20--%3E%20HM%5B%22%E5%BC%80%E7%A1%AC%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20HM%20--%3E%20SI%5B%22%E4%B8%BB%E5%88%BB%E7%A1%85%20%2F%20%E4%BB%8B%E8%B4%A8%22%5D%0A%20%20SI%20--%3E%20OX%5B%22%E8%BF%87%E5%88%BB%E4%B8%8E%E5%8E%BB%E8%83%B6%22%5D%0A%20%20ION%5B%22%E5%AE%9A%E5%90%91%E7%A6%BB%E5%AD%90%22%5D%20--%3E%20RIE%5B%22RIE%20%E5%8D%8F%E5%90%8C%22%5D%0A%20%20RAD%5B%22%E4%B8%AD%E6%80%A7%E8%87%AA%E7%94%B1%E5%9F%BA%22%5D%20--%3E%20RIE%0A%20%20RIE%20--%3E%20HM%0A%20%20RIE%20--%3E%20SI%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h3",{id:"终点与过刻不是光学焦深",tabindex:"-1"},[r("终点与过刻不是光学焦深 "),E("a",{class:"header-anchor",href:"#终点与过刻不是光学焦深","aria-label":'Permalink to "终点与过刻不是光学焦深"'},"​")],-1)),a[4]||(a[4]=E("p",null,"光学窗在剂量–焦点平面；刻蚀窗在终点信号与过刻百分比。开完硬掩模必须过刻，否则局部残膜变短路或开路。过刻吃的是选择比：够，CD 几乎停；不够，CD 随过刻线性漂，校准课的紧凑偏置就不是常数。本课不写某台国产刻蚀机的片/小时，只要求把 AEI 目标从曝光机规格里拆出去。",-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"Coburn–Winters 协同把「化学反应」和「离子辅助脱附」乘在一起：表面先被自由基改性，离子再把改性层打掉或激活。侧壁离子通量小，钝化得以留下，剖面各向异性。这与溅射刻蚀的物理打磨不同，也与湿法的各向同性不同。转移函数可以放大或缩小 CD，也可以把 LWR 的高频滤掉、把低频留下，所以「光刻分辨率」若停在显影后，最终栅极边仍可能被这一段改写。",-1)),(t(),n(o,null,{default:e(()=>[A(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20FREE%5B%22%E8%87%AA%E7%94%B1%E5%9F%BA%E6%94%B9%E6%80%A7%E8%A1%A8%E9%9D%A2%22%5D%20--%3E%20BOT%5B%22%E5%BA%95%E9%9D%A2%3A%20%E5%9E%82%E7%9B%B4%E7%A6%BB%E5%AD%90%E6%89%93%E6%8E%89%E6%94%B9%E6%80%A7%E5%B1%82%22%5D%0A%20%20BOT%20--%3E%20ANISO%5B%22%E7%BA%B5%E5%90%91%E5%BF%AB%E9%80%9F%E6%8E%A8%E8%BF%9B%22%5D%0A%20%20SIDE%5B%22%E4%BE%A7%E5%A3%81%3A%20%E9%92%9D%E5%8C%96%E8%86%9C%E6%B2%89%E7%A7%AF%22%5D%20--%3E%20PROTECT%5B%22%E6%A8%AA%E5%90%91%E8%A2%AB%E6%8C%A1%E4%BD%8F%22%5D%0A%20%20PROTECT%20--%3E%20ANISO%0A%20%20BIAS%5B%22%E5%81%8F%E7%BD%AE%E2%86%91%20%E7%A6%BB%E5%AD%90%E8%83%BD%E9%87%8F%22%5D%20--%3E%20FAST%5B%22%E5%89%96%E9%9D%A2%E6%9B%B4%E7%9B%B4%22%5D%0A%20%20BIAS%20--%3E%20COST%5B%22%E6%8D%9F%E4%BC%A4%E2%86%91%20%E9%80%89%E6%8B%A9%E6%AF%94%E2%86%93%22%5D%0A%20%20PASSGAS%5B%22%E5%90%AB%E6%B0%9F%E7%A2%B3%E8%81%9A%E5%90%88%E7%89%A9%E6%B0%94%E4%BD%93%22%5D%20--%3E%20SIDE%0A%20%20PASSGAS%20--%3E%20SEAL%5B%22%E8%BF%87%E9%87%8F%20%E2%86%92%20%E4%BE%A7%E5%A3%81%E5%B0%81%E5%8F%A3%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>多重图形里，第一次 RIE 的结果是第二次涂胶的形貌，反射与涂覆均匀性都变。<a href="/litho/lele-multipattern">LELE</a> 不是两次快门，是两次曝光–刻蚀串联。SADP 的 spacer 厚度在这一段定义，不在空中像里定义。</p><p><span class="marginnote">数字实例：硬掩模对硅选择比 10:1 时，过刻 20% 深度只多啃掉等效 2% 的掩模厚度，开口几乎不动；选择比掉到 2:1，同样过刻要吃掉 10% 掩模，CD 明显变宽。「敢不敢过刻」由这个比值决定。</span></p><p><span class="marginnote">术语翻译：「过刻」是主刻到达层界面后再多刻一段（如 10-20%），保证没有局部残膜短路；「钝化」是刻意在侧壁沉积聚合物当「防护漆」。一多一少都坏事：过刻不够留残膜，钝化过头封死开口。</span></p><p><span class="marginnote">选择比是对特定膜对、特定偏置的窗口，不是材料表上的一个永久数字。换硬掩模或换胶，协同点要重标。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是等离子体源设计课，不写 ICP 线圈匝数。也不把 ALE 的「每循环一埃」提前写成 RIE 的升级开关——循环刻蚀在薄膜课。RIE 不修复套刻，不抬 \\(k_1\\)；它只把已有浮雕变成衬底图形。损伤、电荷与聚合物残留会进电学变差，看起来像光刻热点，根因在过刻和偏置。</p><p>不要用某一代逻辑的良率证明「有 RIE 所以一定差」。转印链的责任隔离是：光学出空中像，胶出浮雕，RIE 出永久边。下一课才问：同样的食谱，为什么密区和疏区、浅槽和深孔速率不同。</p><p><span class="marginnote">出处：J. W. Coburn, H. F. Winters 对离子辅助气体表面化学与等离子体刻蚀机制的公开论述；刻蚀教材中的 RIE 各向异性与选择比。不编造未公开的硅刻蚀速率表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RIE 用离子与自由基协同，把胶浮雕转到硬掩模和硅，是光刻链的最后一次「成像」。</li><li>薄胶先转硬掩模；ADI 与 AEI 的 CD 不是同一个量。</li><li>Coburn–Winters 协同解释各向异性与选择比窗口，不是纯溅射也不是纯湿法。</li><li>OPC 里的刻蚀偏置是这一段的紧凑影子，腔体一漂核就谎。</li><li>深宽比与负荷下一课。</li><li>出处：Coburn–Winters；刻蚀教材中的图形转印。</li></ul>',10))])}const c=s(d,[["render",D]]);export{S as __pageData,c as default};
